[{"order":1,"type":"heading","text":"Mastering Association Mappings in JPA: One-to-One, One-to-Many, Many-to-One, and Many-to-Many"},{"order":2,"type":"paragraph","text":"Java Persistence API (JPA) association mappings define how relational database tables relate to one another within an object-oriented paradigm. Understanding how to configure these relationships is crucial for building robust enterprise Java applications."},{"order":3,"type":"heading","text":"1. One-to-One Associations"},{"order":4,"type":"paragraph","text":"A One-to-One association links a single instance of an entity to a single instance of another entity. A classic example is a User and a UserProfile relationship."},{"order":5,"type":"code","text":"@Entity
@Table(name = "users")
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String username;

    @OneToOne(cascade = CascadeType.ALL, mappedBy = "user")
    private UserProfile profile;
}

@Entity
@Table(name = "user_profiles")
public class UserProfile {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String bio;

    @OneToOne
    @JoinColumn(name = "user_id")
    private User user;
}"},{"order":6,"type":"heading","text":"2. Many-to-One and One-to-Many Associations"},{"order":7,"type":"paragraph","text":"These are the most common relationship types. A Many-to-One association exists when many instances of one entity relate to a single instance of another. Conversely, One-to-Many is the inverse perspective. For instance, many Orders belong to a single Customer."},{"order":8,"type":"code","text":"@Entity
@Table(name = "customers")
public class Customer {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    @OneToMany(mappedBy = "customer", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Order> orders = new ArrayList<>();
}

@Entity
@Table(name = "orders")
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private LocalDate orderDate;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "customer_id", nullable = false)
    private Customer customer;
}"},{"order":9,"type":"heading","text":"3. Many-to-Many Associations"},{"order":10,"type":"paragraph","text":"A Many-to-Many association connects multiple instances of an entity to multiple instances of another entity. This requires a join table to manage the mapping. A common example is Students and Courses."},{"order":11,"type":"code","text":"@Entity
@Table(name = "students")
public class Student {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String name;

    @ManyToMany
    @JoinTable(
        name = "student_course",
        joinColumns = @JoinColumn(name = "student_id"),
        inverseJoinColumns = @JoinColumn(name = "course_id")
    )
    private Set<Course> courses = new HashSet<>();
}

@Entity
@Table(name = "courses")
public class Course {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String title;

    @ManyToMany(mappedBy = "courses")
    private Set<Student> students = new HashSet<>();
}"},{"order":12,"type":"heading","text":"Best Practices for JPA Mappings"},{"order":13,"type":"bullet_point","text":"Always use FetchType.LAZY for To-Many relationships to avoid performance degradation and unintended eager fetching."},{"order":14,"type":"bullet_point","text":"Manage bidirectional relationships carefully by providing helper methods to synchronize both sides of the association."},{"order":15,"type":"bullet_point","text":"Leverage orphanRemoval = true on One-to-Many relationships to automatically clean up child entities when they are unlinked from the parent."}]
